package com.codeguardian.service.largefile; import com.github.javaparser.StaticJavaParser; import org.springframework.stereotype.Service; import java.util.*; @Service public class AstCodeSlicer{public List<CodeSlice> slice(String code,String language,int maxChars){if(code==null)return List.of();if("JAVA".equalsIgnoreCase(language))try{var unit=StaticJavaParser.parse(code);List<CodeSlice> out=new ArrayList<>();int i=0;for(var m:unit.findAll(com.github.javaparser.ast.body.MethodDeclaration.class)){String s=m.toString();out.add(CodeSlice.builder().content(s).startLine(m.getBegin().map(x->x.line).orElse(1)).endLine(m.getEnd().map(x->x.line).orElse(1)).index(i++).build());}if(!out.isEmpty())return out;}catch(Exception ignored){}List<CodeSlice> out=new ArrayList<>();String[] lines=code.split("\\R");StringBuilder b=new StringBuilder();int start=1,i=0;for(int n=0;n<lines.length;n++){if(b.length()+lines[n].length()>maxChars&&b.length()>0){out.add(CodeSlice.builder().content(b.toString()).startLine(start).endLine(n).index(i++).build());b.setLength(0);start=n+1;}b.append(lines[n]).append('\n');}if(b.length()>0)out.add(CodeSlice.builder().content(b.toString()).startLine(start).endLine(lines.length).index(i).build());return out;}}
